  return {body:el('ps-body').value,label:el('ps-label').value,name:el('ps-name').value,
    shape:previous?.shape==='round'?'round':'square',enabled:el('ps-enabled').checked,
    appearance:el('ps-appearance-image').checked?'image':'text',
